package dev.metallicarts.test;
import dev.metallicarts.MetallicArts;
import dev.metallicarts.api.ArtsProtection;
import dev.metallicarts.arts.*;
import dev.metallicarts.allomancy.*;
import dev.metallicarts.domain.*;
import dev.metallicarts.equipment.*;
import dev.metallicarts.feruchemy.*;
import dev.metallicarts.registry.ModRegistries;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.fabricmc.loader.api.FabricLoader;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.core.BlockPos;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.item.*;
import java.util.*;

public final class ReleaseCandidateGameTest {
 private static MetalmindAsset asset(Mob mob){return MetalmindLedger.get(mob.level().getServer()).owned(mob.getAttachedOrCreate(ModRegistries.CONTACT_EQUIPMENT).item(0).get(ModRegistries.METALMIND).token(),new AssetLease(mob.getUUID(),0));}
 @GameTest public void npcActuallySurrendersAttributesThenSpendsCanonicalCharge(GameTestHelper c){var mob=c.spawn(EntityType.ZOMBIE,new BlockPos(2,2,2));mob.setAttached(ModRegistries.SPIRITWEB,Spiritweb.empty());AdvancedSystemsGameTest.grant(mob,Art.FERUCHEMY,Metal.STEEL);NpcFeruchemy.tick(mob);c.assertTrue(asset(mob).charge()==250&&mob.getAttribute(Attributes.MOVEMENT_SPEED).getModifier(MetallicArts.id("f_speed")).amount()<0,"Real slower storage credits exact charge");var target=AdvancedSystemsGameTest.player(c);mob.setTarget(target);NpcFeruchemy.tick(mob);c.assertTrue(asset(mob).charge()==0&&NpcFeruchemy.effect(mob,FeruchemicalAttribute.SPEED)==.25,"Partial last tap spends exact finite balance");var token=asset(mob).token();NpcFeruchemy.release(mob);c.assertTrue(MetalmindLedger.get(c.getLevel().getServer()).find(token.instance()).orElseThrow().lease().isEmpty()&&mob.getAttachedOrCreate(ModRegistries.CONTACT_EQUIPMENT).item(0).isEmpty(),"Death/explicit release frees one physical ring");c.succeed();}
 @GameTest public void npcGoldStorageCostsActualHealthAndRestConsumesNutrition(GameTestHelper c){var mob=c.spawn(EntityType.ZOMBIE,new BlockPos(2,2,2));mob.setAttached(ModRegistries.SPIRITWEB,Spiritweb.empty());AdvancedSystemsGameTest.grant(mob,Art.FERUCHEMY,Metal.GOLD);mob.tickCount=1;float health=mob.getHealth();NpcFeruchemy.tick(mob);c.assertTrue(mob.getHealth()==health-.25f&&asset(mob).charge()==250,"Gold storage is not free");mob.setTarget(AdvancedSystemsGameTest.player(c));NpcFeruchemy.tick(mob);c.assertTrue(mob.getHealth()==health&&asset(mob).charge()==0,"Healing spends precisely the stored health");c.succeed();}
 @GameTest public void npcNicrosilSurrendersOnlyItsTypedAbilityWithoutEditingRawGrants(GameTestHelper c){var mob=c.spawn(EntityType.ZOMBIE,new BlockPos(2,2,2));mob.setAttached(ModRegistries.SPIRITWEB,Spiritweb.empty());AdvancedSystemsGameTest.grant(mob,Art.ALLOMANCY,Metal.STEEL);AdvancedSystemsGameTest.grant(mob,Art.ALLOMANCY,Metal.IRON);AdvancedSystemsGameTest.grant(mob,Art.FERUCHEMY,Metal.NICROSIL);var raw=mob.getAttachedOrCreate(ModRegistries.SPIRITWEB);NpcFeruchemy.tick(mob);c.assertTrue(NpcFeruchemy.access(mob,raw,Art.ALLOMANCY,Metal.STEEL)==.75&&NpcFeruchemy.access(mob,raw,Art.ALLOMANCY,Metal.IRON)==1&&raw.equals(mob.getAttachedOrCreate(ModRegistries.SPIRITWEB)),"Only actually stored typed access is surrendered");mob.setTarget(AdvancedSystemsGameTest.player(c));NpcFeruchemy.tick(mob);c.assertTrue(NpcFeruchemy.access(mob,raw,Art.ALLOMANCY,Metal.STEEL)==1.25&&asset(mob).charge()==0,"Finite paid typed restoration");c.succeed();}
 @GameTest public void npcCopperStoresObservedRouteAndConsumesItForRetreat(GameTestHelper c){var mob=c.spawn(EntityType.ZOMBIE,new BlockPos(2,2,2));mob.setAttached(ModRegistries.SPIRITWEB,Spiritweb.empty());AdvancedSystemsGameTest.grant(mob,Art.FERUCHEMY,Metal.COPPER);mob.tickCount=100;NpcFeruchemy.tick(mob);c.assertTrue(asset(mob).content().memories().size()==1&&asset(mob).charge()==1000,"One actual observed route stored");NpcFeruchemy.tick(mob);c.assertTrue(asset(mob).content().memories().size()==1,"Same place is not fabricated repeatedly");mob.setHealth(5);mob.setTarget(AdvancedSystemsGameTest.player(c));NpcFeruchemy.tick(mob);c.assertTrue(asset(mob).charge()==0&&mob.getAttachedOrCreate(ModRegistries.JOURNAL).memories().size()==1,"Exact memory returned once");c.succeed();}
 @GameTest public void metalForceProtectionDenialPreventsBothTargetMotionAndRecoil(GameTestHelper c){var p=AdvancedSystemsGameTest.player(c);var item=new net.minecraft.world.entity.item.ItemEntity(c.getLevel(),p.getX()+2,p.getY()+1,p.getZ(),new ItemStack(Items.IRON_INGOT));c.getLevel().addFreshEntity(item);ArtsProtection.ENTITY_EVENT.register((actor,target,action)->target!=item);p.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);item.setDeltaMovement(net.minecraft.world.phys.Vec3.ZERO);MetalPhysics.apply(p,new MetalPhysics.Target(item.position(),item,1,false),1,true,AllomancyConfig.DEFAULT);c.assertTrue(item.getDeltaMovement().lengthSqr()==0&&p.getDeltaMovement().lengthSqr()==0,"Protected item cannot become a force/recoil anchor");c.succeed();}
 @GameTest public void actualOpenPacClaimDeniesStrangerAndAllowsOwner(GameTestHelper c)throws Exception{
  if(!FabricLoader.getInstance().isModLoaded("openpartiesandclaims")){c.succeed();return;}
  var owner=AdvancedSystemsGameTest.player(c);var stranger=AdvancedSystemsGameTest.player(c);var pos=new BlockPos(10000,88,10000);c.getLevel().getChunkAt(pos);owner.teleportTo(10000.5,88,10000.5);stranger.teleportTo(10002.5,88,10000.5);
  var apiType=Class.forName("xaero.pac.common.server.api.OpenPACServerAPI");var api=apiType.getMethod("get",net.minecraft.server.MinecraftServer.class).invoke(null,c.getLevel().getServer());var manager=apiType.getMethod("getServerClaimsManager").invoke(api);var managerType=Class.forName("xaero.pac.common.server.claims.api.IServerClaimsManagerAPI");var dim=c.getLevel().dimension().identifier();
  managerType.getMethod("tryToClaim",net.minecraft.resources.Identifier.class,UUID.class,int.class,net.minecraft.resources.Identifier.class,int.class,int.class,int.class,int.class,boolean.class).invoke(manager,dim,owner.getUUID(),0,dim,pos.getX()>>4,pos.getZ()>>4,pos.getX()>>4,pos.getZ()>>4,true);
  c.assertTrue(managerType.getMethod("get",net.minecraft.resources.Identifier.class,BlockPos.class).invoke(manager,dim,pos)!=null,"Actual third-party claim exists");
  c.assertFalse(ArtsProtection.BLOCK_EVENT.invoker().allow(stranger,pos,ArtsProtection.Action.MOVE_BLOCK),"Stranger cannot lift a claimed block");c.assertTrue(ArtsProtection.BLOCK_EVENT.invoker().allow(owner,pos,ArtsProtection.Action.MOVE_BLOCK),"Owner retains access");c.assertFalse(dev.metallicarts.compat.OpenPacAdapter.temporalAllowed(stranger,c.getLevel(),pos),"Temporal processing cannot bypass claim access");var cargo=new net.minecraft.world.entity.item.ItemEntity(c.getLevel(),pos.getX()+.5,pos.getY(),pos.getZ()+.5,new ItemStack(Items.IRON_INGOT));c.getLevel().addFreshEntity(cargo);c.assertFalse(ArtsProtection.ENTITY_EVENT.invoker().allow(stranger,cargo,ArtsProtection.Action.FORCE),"Claim access also guards loose cargo and recoil anchors");c.assertTrue(ArtsProtection.ENTITY_EVENT.invoker().allow(owner,cargo,ArtsProtection.Action.FORCE),"Claim owner can move loose cargo");cargo.discard();
  managerType.getMethod("tryToUnclaim",net.minecraft.resources.Identifier.class,UUID.class,net.minecraft.resources.Identifier.class,int.class,int.class,int.class,int.class,boolean.class).invoke(manager,dim,owner.getUUID(),dim,pos.getX()>>4,pos.getZ()>>4,pos.getX()>>4,pos.getZ()>>4,true);c.succeed();
 }
}
